@file:OptIn(androidx.compose.material3.ExperimentalMaterial3Api::class)

package app.voicecloud.feature.economy.ui
import androidx.compose.foundation.layout.*; import androidx.compose.foundation.lazy.*; import androidx.compose.material3.*; import androidx.compose.runtime.*; import androidx.compose.ui.Modifier; import androidx.compose.ui.text.font.FontWeight; import androidx.compose.ui.unit.dp
import app.voicecloud.feature.economy.model.*
@Composable fun EconomyHubScreen(onOpen:(EconomySection)->Unit,onBack:()->Unit){ Scaffold(topBar={TopAppBar(title={Text("Economy & Progression")},navigationIcon={TextButton(onClick=onBack){Text("Back")}})}){p-> LazyColumn(Modifier.fillMaxSize().padding(p),contentPadding=PaddingValues(20.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){ item{Text("Wallet, rewards and progression",style=MaterialTheme.typography.headlineSmall,fontWeight=FontWeight.Bold); Text("All financial entitlement remains server-authoritative.",color=MaterialTheme.colorScheme.onSurfaceVariant)}; items(EconomySection.entries){s-> ElevatedCard(onClick={onOpen(s)},modifier=Modifier.fillMaxWidth()){Column(Modifier.padding(18.dp)){Text(s.label,fontWeight=FontWeight.SemiBold);Text(s.subtitle,color=MaterialTheme.colorScheme.onSurfaceVariant)}}} } } }
@Composable fun EconomySectionScreen(section:EconomySection,state:EconomyUiState,onLoad:()->Unit,onBack:()->Unit,onClaimCheckIn:()->Unit){ LaunchedEffect(section){onLoad()}; Scaffold(topBar={TopAppBar(title={Text(section.label)},navigationIcon={TextButton(onClick=onBack){Text("Back")}})}){p->LazyColumn(Modifier.fillMaxSize().padding(p),contentPadding=PaddingValues(20.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){ if(state.loading)item{LinearProgressIndicator(Modifier.fillMaxWidth())}; state.error?.let{e->item{Text(e,color=MaterialTheme.colorScheme.error)}}; state.notice?.let{n->item{Text(n,color=MaterialTheme.colorScheme.primary)}}; if(section==EconomySection.VIP)item{AssistChip(onClick={},label={Text("Google Play subscription authority only")})}; if(section==EconomySection.RANKINGS)item{Text("Agency ranking is intentionally unavailable until the backend Agency subsystem exists.")}; if(section==EconomySection.PROGRESSION)item{Button(enabled=!state.busy,onClick=onClaimCheckIn){Text("Claim daily check-in")}}; item{ElevatedCard(Modifier.fillMaxWidth()){Column(Modifier.padding(16.dp)){Text("Live server data",fontWeight=FontWeight.SemiBold);Text(state.payload?.toString()?.take(8000)?:"No data returned.",style=MaterialTheme.typography.bodySmall)}}} } } }
